"use client";
import { Avatar } from "@base-ui/react/avatar";
import { ChevronLeftIcon, ChevronRightIcon, ShieldCheckIcon, ShieldOffIcon } from "lucide-react";

import {
  EmployeeActions,
  type EmployeeActionCallbacks,
} from "@/components/plugins/employees/employee-actions";
import { EmployeeCreateDialog } from "@/components/plugins/employees/employee-create-dialog";
import { employeeLabels, type EmployeeLabels } from "@/components/plugins/employees/labels";
import {
  EMPLOYEE_PAGE_SIZE,
  isEmployeeAdmin,
  type CreateEmployee,
  type Employee,
} from "@/components/plugins/employees/schema";
import { outlineButtonClass } from "@/components/plugins/employees/styles";
import { cn } from "@/components/utils/cn";
export { EmployeeCreateDialog } from "@/components/plugins/employees/employee-create-dialog";
export type {
  Employee,
  CreateEmployee,
  UpdateEmployee,
  VerificationResult,
} from "@/components/plugins/employees/schema";
export type { EmployeeLabels } from "@/components/plugins/employees/labels";
export interface EmployeesPageProps extends EmployeeActionCallbacks {
  employees: readonly Employee[];
  currentUserId: string;
  /** Role from the host's authenticated session. Missing or non-admin roles render nothing. */
  currentUserRole: string | null | undefined;
  total: number;
  offset: number;
  onOffsetChange: (offset: number) => void;
  onCreate: (values: CreateEmployee) => Promise<void>;
  loading?: boolean;
  error?: boolean;
  labels?: Partial<EmployeeLabels>;
  className?: string;
}
export function EmployeesPage({
  employees,
  currentUserId,
  currentUserRole,
  total,
  offset,
  onOffsetChange,
  onCreate,
  loading = false,
  error = false,
  onUpdate,
  onDelete,
  onSendVerification,
  labels: overrides,
  className,
}: EmployeesPageProps) {
  if (!isEmployeeAdmin(currentUserRole)) return null;
  const labels = { ...employeeLabels, ...overrides };
  return (
    <section
      className={cn(
        "mx-auto w-full max-w-7xl min-w-0 rounded-xl border border-border bg-card py-6 text-card-foreground",
        className,
      )}
      aria-label={labels.title}
    >
      <header className="flex flex-wrap items-center justify-between gap-4 px-6 pb-6">
        <h1 className="font-sans text-base font-semibold">{labels.title}</h1>
        <EmployeeCreateDialog
          currentUserRole={currentUserRole}
          onCreate={onCreate}
          labels={labels}
        />
      </header>
      <div className="px-6">
        {loading ? (
          <output>{labels.loading}</output>
        ) : error ? (
          <p role="alert" className="text-destructive">
            {labels.error}
          </p>
        ) : (
          <>
            <div className="min-w-0 overflow-x-auto">
              <table className="w-full caption-bottom text-sm">
                <thead className="[&_tr]:border-b">
                  <tr className="border-b border-border transition-colors hover:bg-muted/50">
                    <th
                      scope="col"
                      className="h-10 px-2 text-left align-middle font-medium whitespace-nowrap"
                    >
                      {labels.name}
                    </th>
                    <th
                      scope="col"
                      className="h-10 px-2 text-left align-middle font-medium whitespace-nowrap"
                    >
                      {labels.email}
                    </th>
                    <th
                      scope="col"
                      className="h-10 px-2 text-left align-middle font-medium whitespace-nowrap"
                    >
                      {labels.role}
                    </th>
                    <th
                      scope="col"
                      className="h-10 px-2 text-left align-middle font-medium whitespace-nowrap"
                    >
                      {labels.status}
                    </th>
                    <th
                      scope="col"
                      className="sticky right-0 z-10 bg-card p-2 text-right align-middle whitespace-nowrap"
                    >
                      {labels.actions}
                    </th>
                  </tr>
                </thead>
                <tbody className="[&_tr:last-child]:border-0">
                  {employees.map((employee) => (
                    <tr key={employee.id} className="border-b border-border hover:bg-muted/50">
                      <td aria-label={employee.name} className="p-2 align-middle whitespace-nowrap">
                        <div className="flex items-center gap-3">
                          <Avatar.Root className="relative flex size-8 shrink-0 overflow-hidden rounded-full bg-muted">
                            <Avatar.Image
                              className="size-full object-cover"
                              src={employee.image ?? undefined}
                              alt=""
                            />
                            <Avatar.Fallback className="flex size-full items-center justify-center text-xs">
                              {employee.name
                                .trim()
                                .split(/\s+/)
                                .slice(0, 2)
                                .map((part) => part.charAt(0))
                                .join("")
                                .toUpperCase()}
                            </Avatar.Fallback>
                          </Avatar.Root>
                          <span className="max-w-48 truncate font-medium" title={employee.name}>
                            {employee.name}
                          </span>
                        </div>
                      </td>
                      <td className="p-2 align-middle whitespace-nowrap">
                        <div className="flex items-center gap-3">
                          <span
                            role="img"
                            aria-label={
                              employee.emailVerified ? labels.verified : labels.unverified
                            }
                            title={employee.emailVerified ? labels.verified : labels.unverified}
                            className={
                              employee.emailVerified
                                ? "text-green-600 dark:text-green-400"
                                : "text-muted-foreground"
                            }
                          >
                            {employee.emailVerified ? (
                              <ShieldCheckIcon className="size-4" aria-hidden="true" />
                            ) : (
                              <ShieldOffIcon className="size-4" aria-hidden="true" />
                            )}
                          </span>
                          <span className="max-w-72 truncate" title={employee.email}>
                            {employee.email}
                          </span>
                        </div>
                      </td>
                      <td className="p-2 align-middle whitespace-nowrap">
                        {isEmployeeAdmin(employee.role) ? labels.roleAdmin : labels.roleUser}
                      </td>
                      <td className="p-2 align-middle whitespace-nowrap">
                        {employee.banned ? labels.disabled : labels.active}
                      </td>
                      <td className="sticky right-0 z-10 bg-card p-2 text-right align-middle whitespace-nowrap">
                        <EmployeeActions
                          employee={employee}
                          currentUserId={currentUserId}
                          labels={labels}
                          onUpdate={onUpdate}
                          onDelete={onDelete}
                          onSendVerification={onSendVerification}
                        />
                      </td>
                    </tr>
                  ))}
                  {employees.length === 0 && (
                    <tr className="border-b border-border transition-colors hover:bg-muted/50">
                      <td colSpan={5} className="p-2">
                        {labels.empty}
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
            <footer className="mt-5 flex flex-wrap items-center justify-end gap-3">
              <span className="text-sm text-muted-foreground">
                {total} {labels.total}
              </span>
              <button
                type="button"
                className={outlineButtonClass}
                disabled={offset === 0}
                onClick={() => onOffsetChange(offset - EMPLOYEE_PAGE_SIZE)}
                aria-label={labels.previous}
              >
                <ChevronLeftIcon aria-hidden="true" />
              </button>
              <span className="min-w-9 text-center text-sm text-muted-foreground tabular-nums">
                {offset / EMPLOYEE_PAGE_SIZE + 1}/
                {Math.max(1, Math.ceil(total / EMPLOYEE_PAGE_SIZE))}
              </span>
              <button
                type="button"
                className={outlineButtonClass}
                disabled={offset + EMPLOYEE_PAGE_SIZE >= total}
                onClick={() => onOffsetChange(offset + EMPLOYEE_PAGE_SIZE)}
                aria-label={labels.next}
              >
                <ChevronRightIcon aria-hidden="true" />
              </button>
            </footer>
          </>
        )}
      </div>
    </section>
  );
}

"use client";
import { Dialog } from "@base-ui/react/dialog";
import { PlusIcon } from "lucide-react";
import { useId, useRef, useState } from "react";

import { employeeLabels, type EmployeeLabels } from "@/components/plugins/employees/labels";
import {
  createEmployeeSchema,
  isEmployeeAdmin,
  type CreateEmployee,
} from "@/components/plugins/employees/schema";
import {
  dialogClass,
  inputClass,
  outlineButtonClass,
  primaryButtonClass,
} from "@/components/plugins/employees/styles";
import { cn } from "@/components/utils/cn";

export interface EmployeeCreateDialogProps {
  /** Role from the host's authenticated session. Missing or non-admin roles render nothing. */
  currentUserRole: string | null | undefined;
  onCreate: (values: CreateEmployee) => Promise<void>;
  labels?: Partial<EmployeeLabels>;
  className?: string;
}

export function EmployeeCreateDialog({
  currentUserRole,
  onCreate,
  labels: overrides,
  className,
}: EmployeeCreateDialogProps) {
  const labels = { ...employeeLabels, ...overrides };
  const id = useId();
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [failed, setFailed] = useState(false);
  const lock = useRef(false);
  if (!isEmployeeAdmin(currentUserRole)) return null;

  async function submit(form: HTMLFormElement) {
    if (lock.current) return;
    const data = new FormData(form);
    lock.current = true;
    setPending(true);
    setFailed(false);
    try {
      await onCreate(createEmployeeSchema.parse(Object.fromEntries(data)));
      form.reset();
      setOpen(false);
    } catch {
      setFailed(true);
    } finally {
      lock.current = false;
      setPending(false);
    }
  }

  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (pending) return;
        setFailed(false);
        setOpen(next);
      }}
    >
      <Dialog.Trigger className={cn(primaryButtonClass, className)}>
        <PlusIcon aria-hidden="true" />
        {labels.add}
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup className={dialogClass}>
          <div className="space-y-2">
            <Dialog.Title className="text-lg font-semibold">{labels.add}</Dialog.Title>
            <Dialog.Description className="text-sm text-muted-foreground">
              {labels.instructions}
            </Dialog.Description>
          </div>
          <form
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              void submit(event.currentTarget);
            }}
          >
            <div className="grid gap-2">
              <label htmlFor={`${id}-name`}>{labels.name}</label>
              <input
                className={inputClass}
                id={`${id}-name`}
                name="name"
                autoComplete="name"
                maxLength={200}
                required
                readOnly={pending}
              />
            </div>
            <div className="grid gap-2">
              <label htmlFor={`${id}-email`}>{labels.email}</label>
              <input
                className={inputClass}
                id={`${id}-email`}
                name="email"
                type="email"
                autoComplete="email"
                required
                readOnly={pending}
              />
            </div>
            <div className="grid gap-2">
              <label htmlFor={`${id}-password`}>{labels.password}</label>
              <input
                className={inputClass}
                id={`${id}-password`}
                name="password"
                type="password"
                autoComplete="new-password"
                minLength={8}
                maxLength={128}
                required
                readOnly={pending}
              />
            </div>
            <div className="grid gap-2">
              <label htmlFor={`${id}-role`}>{labels.role}</label>
              <select
                id={`${id}-role`}
                name="role"
                defaultValue="user"
                disabled={pending}
                className="h-9 rounded-lg border bg-background px-3 text-sm"
              >
                <option value="user">{labels.roleUser}</option>
                <option value="admin">{labels.roleAdmin}</option>
              </select>
            </div>
            {failed && (
              <p role="alert" className="text-destructive">
                {labels.createError}
              </p>
            )}
            <div className="flex justify-end gap-3">
              <Dialog.Close type="button" className={outlineButtonClass} disabled={pending}>
                {labels.cancel}
              </Dialog.Close>
              <button className={primaryButtonClass} type="submit" disabled={pending}>
                {pending ? labels.adding : labels.save}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

"use client";
import { Dialog } from "@base-ui/react/dialog";
import { PencilIcon, SendHorizontalIcon, Trash2Icon } from "lucide-react";
import { useRef, useState } from "react";

import { employeeLabels, type EmployeeLabels } from "@/components/plugins/employees/labels";
import {
  isEmployeeAdmin,
  updateEmployeeSchema,
  type Employee,
  type UpdateEmployee,
  type VerificationResult,
} from "@/components/plugins/employees/schema";
import {
  buttonClass,
  iconButtonClass,
  primaryButtonClass,
  outlineButtonClass,
  inputClass,
  dialogClass,
} from "@/components/plugins/employees/styles";
import { cn } from "@/components/utils/cn";
export interface EmployeeActionCallbacks {
  onUpdate: (values: UpdateEmployee) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
  /** @deprecated The employee list no longer provides an access toggle. */
  onSetBan?: (id: string, banned: boolean) => Promise<void>;
  onSendVerification: (id: string) => Promise<VerificationResult>;
}
export interface EmployeeActionsProps extends EmployeeActionCallbacks {
  employee: Employee;
  currentUserId: string;
  labels?: Partial<EmployeeLabels>;
  className?: string;
}
export function EmployeeActions({
  employee,
  currentUserId,
  onUpdate,
  onDelete,
  onSendVerification,
  labels: overrides,
  className,
}: EmployeeActionsProps) {
  const labels = { ...employeeLabels, ...overrides };
  const [editing, setEditing] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [pending, setPending] = useState(false);
  const [failedAction, setFailedAction] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ error: boolean; message: string } | null>(null);
  const lock = useRef(false);
  const isSelf = employee.id === currentUserId;
  async function run(kind: "edit" | "remove" | "send", action: () => Promise<void>) {
    if (lock.current) return;
    lock.current = true;
    setPending(true);
    setFailedAction(null);
    setFeedback(null);
    try {
      await action();
    } catch {
      setFailedAction(kind);
      if (kind === "send")
        setFeedback({
          error: true,
          message: labels.emailError,
        });
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return (
    <div className={cn("flex flex-col items-end gap-1", className)}>
      <div className="flex items-center justify-end gap-1">
        {!employee.emailVerified && (
          <button
            type="button"
            className={iconButtonClass}

            disabled={pending}
            aria-label={`${labels.sendEmail} ${employee.name}`}
            onClick={() =>
              void run("send", async () => {
                const { status } = await onSendVerification(employee.id);
                setFeedback({
                  error: status === "unavailable",
                  message:
                    status === "unavailable"
                      ? labels.emailUnavailable
                      : status === "verified"
                        ? labels.verified
                        : labels.emailSent,
                });
              })
            }
          >
            <SendHorizontalIcon aria-hidden="true" />
          </button>
        )}
        <Dialog.Root
          open={editing}
          onOpenChange={(open) => {
            if (!pending) {
              setFailedAction(null);
              setEditing(open);
            }
          }}
        >
          <Dialog.Trigger
            disabled={pending}
            className={iconButtonClass}

            aria-label={`${labels.edit} ${employee.name}`}
          >
            <PencilIcon aria-hidden="true" />
          </Dialog.Trigger>
          <Dialog.Portal>
            <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
            <Dialog.Popup className={dialogClass}>
              <div className="space-y-2">
                <Dialog.Title className="text-lg font-semibold">{labels.editTitle}</Dialog.Title>
                <Dialog.Description className="text-sm text-muted-foreground">
                  {labels.editDescription}
                </Dialog.Description>
              </div>
              <form
                className="space-y-4"
                onSubmit={(event) => {
                  event.preventDefault();
                  const data = new FormData(event.currentTarget);
                  void run("edit", async () => {
                    await onUpdate(
                      updateEmployeeSchema.parse({
                        ...Object.fromEntries(data),
                        id: employee.id,
                        role: isSelf ? "admin" : data.get("role"),
                      }),
                    );
                    setEditing(false);
                  });
                }}
              >
                <div className="grid gap-2">
                  <label htmlFor={`name-${employee.id}`}>{labels.name}</label>
                  <input
                    className={inputClass}
                    id={`name-${employee.id}`}
                    name="name"
                    defaultValue={employee.name}
                    maxLength={200}
                    required
                    readOnly={pending}
                  />
                </div>
                <div className="grid gap-2">
                  <label htmlFor={`email-${employee.id}`}>{labels.email}</label>
                  <input
                    className={inputClass}
                    id={`email-${employee.id}`}
                    name="email"
                    type="email"
                    defaultValue={employee.email}
                    required
                    readOnly={pending}
                  />
                </div>
                <div className="grid gap-2">
                  <label htmlFor={`role-${employee.id}`}>{labels.role}</label>
                  <select
                    id={`role-${employee.id}`}
                    name="role"
                    defaultValue={isEmployeeAdmin(employee.role) ? "admin" : "user"}
                    disabled={pending || isSelf}
                    className="h-9 rounded-lg border bg-background px-3 text-sm"
                  >
                    <option value="user">{labels.roleUser}</option>
                    <option value="admin">{labels.roleAdmin}</option>
                  </select>
                </div>
                {failedAction === "edit" && (
                  <p role="alert" className="text-destructive">
                    {labels.editError}
                  </p>
                )}
                <div className="flex justify-end gap-3">
                  <button
                    type="button"
                    className={outlineButtonClass}
                    disabled={pending}
                    onClick={() => setEditing(false)}
                  >
                    {labels.cancel}
                  </button>
                  <button type="submit" className={primaryButtonClass} disabled={pending}>
                    {pending ? labels.saving : labels.saveChanges}
                  </button>
                </div>
              </form>
            </Dialog.Popup>
          </Dialog.Portal>
        </Dialog.Root>
        {!isSelf && (
          <Dialog.Root
            open={deleting}
            onOpenChange={(open) => {
              if (!pending) {
                setFailedAction(null);
                setDeleting(open);
              }
            }}
          >
            <Dialog.Trigger
              disabled={pending}
              className={cn(iconButtonClass, "text-destructive hover:text-destructive")}
              aria-label={`${labels.delete} ${employee.name}`}
            >
              <Trash2Icon aria-hidden="true" />
            </Dialog.Trigger>
            <Dialog.Portal>
              <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
              <Dialog.Popup className={dialogClass}>
                <div className="space-y-2">
                  <Dialog.Title className="text-lg font-semibold">
                    {labels.deleteTitle}
                  </Dialog.Title>
                  <Dialog.Description className="text-sm text-muted-foreground">
                    {labels.deleteDescription.replace("{name}", employee.name)}
                  </Dialog.Description>
                </div>
                {failedAction === "remove" && (
                  <p role="alert" className="text-destructive">
                    {labels.deleteError}
                  </p>
                )}
                <div className="flex justify-end gap-3">
                  <button
                    type="button"
                    className={outlineButtonClass}
                    disabled={pending}
                    onClick={() => setDeleting(false)}
                  >
                    {labels.cancel}
                  </button>
                  <button
                    type="button"
                    className={cn(
                      buttonClass,
                      "bg-destructive text-destructive-foreground hover:bg-destructive/90",
                    )}
                    disabled={pending}
                    onClick={() =>
                      void run("remove", async () => {
                        await onDelete(employee.id);
                        setDeleting(false);
                      })
                    }
                  >
                    {pending ? labels.deleting : labels.delete}
                  </button>
                </div>
              </Dialog.Popup>
            </Dialog.Portal>
          </Dialog.Root>
        )}
      </div>
      {feedback && (
        <p
          role={feedback.error ? "alert" : "status"}
          className={cn(
            "max-w-60 text-xs whitespace-normal",
            feedback.error ? "text-destructive" : "text-muted-foreground",
          )}
        >
          {feedback.message}
        </p>
      )}
    </div>
  );
}

import { z } from "zod";

export const employeeRoleSchema = z.enum(["user", "admin"]);

export const createEmployeeSchema = z.object({
  name: z.string().trim().min(1).max(200),
  email: z.string().trim().pipe(z.email()),
  password: z.string().min(8).max(128),
  role: employeeRoleSchema.default("user"),
});

export const listEmployeesSchema = z.object({
  offset: z.number().int().nonnegative().default(0),
});

export const setEmployeeBanSchema = z.object({
  id: z.string().min(1),
  banned: z.boolean(),
});

export const employeeIdSchema = z.object({ id: z.string().min(1) });

export const updateEmployeeSchema = createEmployeeSchema.omit({ password: true }).extend({
  id: z.string().min(1),
});

export const EMPLOYEE_PAGE_SIZE = 25;
export type EmployeeRole = z.infer<typeof employeeRoleSchema>;
export type CreateEmployee = z.infer<typeof createEmployeeSchema>;
export type UpdateEmployee = z.infer<typeof updateEmployeeSchema>;
export interface Employee {
  id: string;
  name: string;
  email: string;
  role?: string | null;
  image?: string | null;
  emailVerified: boolean;
  banned?: boolean | null;
}
export type VerificationResult = { status: "sent" | "verified" | "unavailable" };
export function isEmployeeAdmin(role: string | null | undefined): boolean {
  return role?.split(",").includes("admin") ?? false;
}

import { cn } from "@/components/utils/cn";

export const inputClass =
  "h-9 w-full rounded-lg border border-input bg-transparent px-3 text-base shadow-xs outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 md:text-sm";
export const buttonClass =
  "inline-flex min-h-9 items-center justify-center gap-2 rounded-lg px-3 text-sm font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4";
export const primaryButtonClass = `${buttonClass} bg-primary text-primary-foreground hover:bg-primary/90`;
export const outlineButtonClass = `${buttonClass} border border-border hover:bg-accent`;
export const iconButtonClass = cn(
  buttonClass,
  "size-8 min-h-8 shrink-0 p-0 hover:bg-accent hover:text-accent-foreground",
);
export const dialogClass =
  "fixed top-1/2 left-1/2 z-50 w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 space-y-4 rounded-xl border border-border bg-background p-6 text-foreground shadow-lg";
